/**
 * Activity Log Model
 * Stores behavioral analytics events generated by AI server.
 */

const mongoose = require("mongoose");

const activityLogSchema = new mongoose.Schema(
  {
    user_id: {
      type: mongoose.Schema.Types.Mixed,
      required: true,
      index: true,
    },
    task_id: {
      type: mongoose.Schema.Types.ObjectId,
      ref: "Task",
      default: null,
    },
    action_type: {
      type: String,
      required: true,
      index: true,
    },
    action_timestamp: {
      type: Date,
      default: Date.now,
      index: true,
    },
    day_of_week: {
      type: Number,
      min: 0,
      max: 6,
      index: true,
    },
    hour_of_day: {
      type: Number,
      min: 0,
      max: 23,
      index: true,
    },
    week_number: {
      type: Number,
      min: 1,
      max: 53,
    },
    task_priority: {
      type: String,
      enum: ["low", "medium", "high", null],
      default: null,
    },
    subject: {
      type: String,
      default: null,
      trim: true,
    },
    source: {
      type: String,
      default: null,
    },
    time_taken_minutes: {
      type: Number,
      default: null,
      min: 0,
    },
    was_on_time: {
      type: Boolean,
      default: null,
    },
    scheduled_hour: {
      type: Number,
      default: null,
      min: 0,
      max: 23,
    },
    scheduled_day: {
      type: Number,
      default: null,
      min: 0,
      max: 6,
    },
    reschedule_count: {
      type: Number,
      default: 0,
      min: 0,
    },
  },
  {
    collection: "activity_logs",
    timestamps: false,
  },
);

activityLogSchema.index({ user_id: 1, action_type: 1, action_timestamp: -1 });
activityLogSchema.index({ user_id: 1, day_of_week: 1, hour_of_day: 1 });

const ActivityLog = mongoose.model("ActivityLog", activityLogSchema);

module.exports = ActivityLog;
